"""Format identification helpers for Ancient's command line interface."""

import zlib


def _gzip_member(data):
    """Return (plain, trailing bytes) for a raw-deflate gzip member."""
    if len(data) < 10 or data[:2] != b'\x1f\x8b' or data[2] != 8:
        raise ValueError("invalid gzip header")
    flags = data[3]
    if flags & 0xe0:
        raise ValueError("reserved gzip flags")
    pos = 10
    if flags & 4:
        if pos + 2 > len(data): raise ValueError("short gzip extra length")
        size = int.from_bytes(data[pos:pos + 2], 'little')
        pos += 2 + size
    for mask in (8, 16):
        if flags & mask:
            end = data.find(b'\0', pos)
            if end < 0: raise ValueError("unterminated gzip field")
            pos = end + 1
    if flags & 2:
        pos += 2
    if pos > len(data): raise ValueError("short gzip header")
    dec = zlib.decompressobj(-zlib.MAX_WBITS)
    plain = dec.decompress(data[pos:])
    if not dec.eof:
        raise ValueError("incomplete deflate stream")
    return plain, dec.unused_data

def identify(data: bytes):
    """Return Ancient's human-readable compression description, or None."""
    if data.startswith(b'\x1f\x8b') and len(data) >= 11:
        # The reference checks the deflate stream but is permissive about a
        # partially missing trailer (except a four-byte CRC-only remainder).
        try:
            rest = data
            last_plain = b''
            while rest:
                plain, trailer = _gzip_member(rest)
                if len(trailer) >= 18 and trailer[8:10] == b'\x1f\x8b':
                    last_plain = plain
                    rest = trailer[8:]
                    continue
                if len(trailer) not in (0, 5, 6, 7, 8):
                    raise ValueError("invalid gzip trailer length")
                last_plain = plain
                rest = b''
            if last_plain:
                return 'gzip: Deflate'
        except Exception:
            pass
    if data.startswith(b'BZh') and len(data) >= 4 and data[3:4] in b'123456789':
        return 'bz2: bzip2'
    # Unix compress requires a valid LZW stream, not just its two-byte magic.
    if data.startswith(b'\x1f\x9d'):
        try:
            from unixcompress import decompress
            decompress(data)
            return 'Z: Compress (new)' if data[2] & 0x80 else 'Z: Compress (old)'
        except Exception:
