"""Small standard-library decoder backends used by the command line frontend."""
import bz2
import gzip
import zlib
import unixcompress

class GzipVerifyError(Exception):
    """The raw DEFLATE stream decoded, but its gzip CRC did not match."""

def _gzip_decode(data):
    rest = data
    first = None
    last_size = None
    while rest:
        if len(rest) < 10 or rest[:2] != b'\x1f\x8b' or rest[2] != 8:
            return None
        flags = rest[3]
        if flags & 0xe0:
            return None
        pos = 10
        if flags & 4:
            if pos + 2 > len(rest): return None
            pos += 2 + int.from_bytes(rest[pos:pos+2], 'little')
        for mask in (8, 16):
            if flags & mask:
                end = rest.find(b'\0', pos)
                if end < 0: return None
                pos = end + 1
        if flags & 2: pos += 2
        if pos >= len(rest): return None
        dec = zlib.decompressobj(-zlib.MAX_WBITS)
        try:
            plain = dec.decompress(rest[pos:])
        except zlib.error:
            return None
        if not dec.eof:
            return None
        tail = dec.unused_data
        if len(tail) < 8:
            return None
        crc = int.from_bytes(tail[:4], 'little')
        if first is None:
            if (zlib.crc32(plain) & 0xffffffff) != crc:
                return GzipVerifyError()
            first = plain
        last_size = int.from_bytes(tail[4:8], 'little')
        rest = tail[8:]
    if first is None or not first:
        return None
    size = max(len(first), last_size or 0)
    return first[:size].ljust(size, b'\0')


def decode(data: bytes):
    """Return (human-readable format, uncompressed bytes), or None if unsupported.

    Format recognition deliberately uses stream magic; filenames do not influence
    decompression.  gzip.decompress and bz2.decompress both accept concatenated
    members, as the reference utility does for ordinary streams.
    """
    if data.startswith(b'\x1f\x8b'):
        result = _gzip_decode(data)
        if isinstance(result, GzipVerifyError):
            return 'gzip: Deflate', result
        if result is None:
            return 'gzip: Deflate', None
        return 'gzip: Deflate', result
    if data.startswith(b'BZh'):
        # Ancient only treats the signature as a bzip stream when the
        # mandatory block-size digit is present and in range.
        if len(data) < 4 or data[3:4] not in b'123456789':
            return None
        try:
            dec = bz2.BZ2Decompressor()
            plain = dec.decompress(data)
            if not dec.eof:
                return 'bz2: bzip2', None
            return 'bz2: bzip2', plain
        except (OSError, EOFError, ValueError):
            return 'bz2: bzip2', None
    if data.startswith(b'\x1f\x9d'):
        if len(data) == 3:
            flags = data[2]
            maxbits = flags & 0x1f
            if not (flags & 0x60) and 9 <= maxbits <= 16:
                return 'Z: Compress', b''
        try:
            return 'Z: Compress', unixcompress.decompress(data)
        except (ValueError, IndexError):
            return 'Z: Compress', None
    return None

