#!/usr/bin/env python3
import os, sys, time
from identify import identify
from decode import decode, GzipVerifyError
from unixcompress import decompress as decompress_z, InvalidCompress

USAGE = '''Ancient v2.3.0
Copyright (C) Teemu Suutari

Usage: ancient i[dentify] packed_input_files...
 - identifies compression used in a file(s)
Usage: ancient v[erify] packed_input_file unpacked_comparison_file
 - verifies decompression against known good unpacked file
Usage: ancient [-p] d[ecompress] packed_input_file output_file
 - decompresses single file
 - use p-flag to preserve timestamp of the original'''

def read(path):
    try:
        with open(path, 'rb') as f: return f.read()
    except OSError:
        print(f'Could not read file {path}', file=sys.stderr)
        return None

def unpack(data):
    kind = identify(data)
    if kind is None:
        return None
    x = decode(data)
    if x is not None: return x
    if data.startswith(b'\x1f\x9d'):
        try: return (kind, decompress_z(data))
        except (InvalidCompress, IndexError): return (kind, None)
    if data.startswith(b'\x1f\xa0'):
        # The four-byte all-zero header is the valid empty SCO stream.
        return (kind, b'' if data == b'\x1f\xa0\0\0' else None)
    # Formats recognized by signature without a local decoder fail at decode time.
    return (kind, None)

def main(argv):
    preserve = False
    if argv and argv[0] == '-p': preserve=True; argv=argv[1:]
    if not argv:
        print(USAGE,file=sys.stderr); return 255
    op=argv[0]
    if op in ('i','identify'):
        if len(argv)<2: print(USAGE,file=sys.stderr); return 255
        for path in argv[1:]:
            data=read(path)
            if data is None: return 255
            kind=identify(data)
            if kind is None: print(f'Unknown or invalid compression format in file {path}',file=sys.stderr); continue
            print(f'Compression of {path} is {kind}')
        return 0
    if op in ('v','verify'):
        if len(argv)!=3: print(USAGE,file=sys.stderr); return 255
        packed=read(argv[1])
        if packed is None: return 255
        expected=read(argv[2])
        if expected is None: return 255
        result=unpack(packed)
        if result is None:
            print(f'Unknown or invalid compression format in file {argv[1]}',file=sys.stderr); return 255
        if isinstance(result[1], GzipVerifyError):
            print(f'Verify (raw) failed for {argv[1]}',file=sys.stderr); return 255
        if result[1] is None:
            message = 'Verify (raw) failed' if len(result) > 2 and result[2] == 'verify' else 'Decompression failed'
            print(f'{message} for {argv[1]}',file=sys.stderr); return 255
        actual=result[1]
        if len(actual)!=len(expected): print(f'Verify failed for {argv[1]} and {argv[2]} - sizes differ',file=sys.stderr); return 255
        if actual!=expected:
            pos = next(i for i, (a, b) in enumerate(zip(actual, expected)) if a != b)
            print(f'Verify failed for {argv[1]} and {argv[2]} - contents differ @ {pos}',file=sys.stderr)
            return 255
        print('Files match!'); return 0
    if op in ('d','decompress'):
        if len(argv)!=3: print(USAGE,file=sys.stderr); return 255
        data=read(argv[1])
        if data is None:return 255
        result=unpack(data)
        if result is None:
            print(f'Unknown or invalid compression format in file {argv[1]}',file=sys.stderr); return 255
        if isinstance(result[1], GzipVerifyError):
            print(f'Verify (raw) failed for {argv[1]}',file=sys.stderr); return 255
        if result[1] is None:
            message = 'Verify (raw) failed' if len(result) > 2 and result[2] == 'verify' else 'Decompression failed'
            print(f'{message} for {argv[1]}',file=sys.stderr); return 255
        try:
            with open(argv[2],'wb') as f:f.write(result[1])
            if preserve:
                source_stat = os.stat(argv[1])
                os.utime(argv[2], (int(source_stat.st_atime), int(source_stat.st_mtime)))
        except OSError:
            print(f'Could not write file {argv[2]}',file=sys.stderr); return 0
        return 0
    if len(argv) > 1: print('Unknown command', file=sys.stderr)
    print(USAGE,file=sys.stderr); return 255

if __name__=='__main__': sys.exit(main(sys.argv[1:]))
